import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../App';

const CROPS = ['Wheat', 'Rice', 'Cotton', 'Sugarcane', 'Maize', 'Soybean', 'Tomato', 'Onion'];
const STATES = ['Maharashtra', 'Punjab', 'Uttar Pradesh', 'Madhya Pradesh', 'Rajasthan', 'Gujarat', 'Karnataka', 'Andhra Pradesh'];

export default function AuthPage() {
  const [tab, setTab] = useState('login');
  const [form, setForm] = useState({ name: '', phone: '', password: '', state: '', crop: '', acres: '' });
  const [locating, setLocating] = useState(false);
  const [location, setLocation] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const { setUser } = useAuth();
  const navigate = useNavigate();

  const detectGPS = () => {
    setLocating(true);
    navigator.geolocation?.getCurrentPosition(
      pos => { setLocation({ lat: pos.coords.latitude.toFixed(4), lng: pos.coords.longitude.toFixed(4) }); setLocating(false); },
      () => { setLocation({ lat: '18.5204', lng: '73.8567' }); setLocating(false); }
    );
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setError('');
    if (!form.phone || !form.password) { setError('Please fill all required fields.'); return; }
    setLoading(true);
    setTimeout(() => {
      setUser({ name: form.name || 'Farmer', phone: form.phone, location: form.state || 'India', crop: form.crop, acres: form.acres, gps: location });
      setLoading(false);
      navigate('/dashboard');
    }, 1200);
  };

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  return (
    <div className="min-h-screen bg-mesh flex items-center justify-center px-4 py-12">
      {/* BG orbs */}
      <div className="fixed top-20 left-20 w-72 h-72 bg-green-500/10 rounded-full blur-3xl pointer-events-none" />
      <div className="fixed bottom-20 right-20 w-96 h-96 bg-green-700/10 rounded-full blur-3xl pointer-events-none" />

      <div className="w-full max-w-md relative z-10 animate-slide-up">
        {/* Logo */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center gap-3 mb-4">
            <div className="w-12 h-12 rounded-2xl btn-primary flex items-center justify-center text-2xl ai-glow">🌿</div>
            <span className="font-display font-bold text-2xl text-white">SmartSheti <span className="gradient-text">AI</span></span>
          </div>
          <p className="text-gray-400 text-sm">India's Smartest Farming Platform</p>
        </div>

        <div className="glass rounded-3xl p-8 border border-green-900/30">
          {/* Tabs */}
          <div className="flex glass-dark rounded-2xl p-1 mb-8">
            {['login', 'register'].map(t => (
              <button key={t} onClick={() => setTab(t)}
                className={`flex-1 py-2.5 rounded-xl text-sm font-semibold transition-all capitalize ${tab === t ? 'btn-primary text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}>
                {t === 'login' ? '🔑 Login' : '🌱 Register'}
              </button>
            ))}
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            {tab === 'register' && (
              <div>
                <label className="text-gray-400 text-xs uppercase tracking-wider mb-1.5 block">Full Name</label>
                <input value={form.name} onChange={e => set('name', e.target.value)} placeholder="Ramesh Kumar"
                  className="w-full bg-black/30 border border-green-900/40 text-white rounded-xl px-4 py-3 text-sm placeholder-gray-600 transition-all" />
              </div>
            )}

            <div>
              <label className="text-gray-400 text-xs uppercase tracking-wider mb-1.5 block">Phone Number *</label>
              <input value={form.phone} onChange={e => set('phone', e.target.value)} placeholder="+91 98765 43210" type="tel"
                className="w-full bg-black/30 border border-green-900/40 text-white rounded-xl px-4 py-3 text-sm placeholder-gray-600 transition-all" />
            </div>

            <div>
              <label className="text-gray-400 text-xs uppercase tracking-wider mb-1.5 block">Password *</label>
              <input value={form.password} onChange={e => set('password', e.target.value)} placeholder="••••••••" type="password"
                className="w-full bg-black/30 border border-green-900/40 text-white rounded-xl px-4 py-3 text-sm placeholder-gray-600 transition-all" />
            </div>

            {tab === 'register' && (
              <>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="text-gray-400 text-xs uppercase tracking-wider mb-1.5 block">State</label>
                    <select value={form.state} onChange={e => set('state', e.target.value)}
                      className="w-full bg-black/30 border border-green-900/40 text-white rounded-xl px-3 py-3 text-sm transition-all">
                      <option value="">Select</option>
                      {STATES.map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="text-gray-400 text-xs uppercase tracking-wider mb-1.5 block">Main Crop</label>
                    <select value={form.crop} onChange={e => set('crop', e.target.value)}
                      className="w-full bg-black/30 border border-green-900/40 text-white rounded-xl px-3 py-3 text-sm transition-all">
                      <option value="">Select</option>
                      {CROPS.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                </div>

                <div>
                  <label className="text-gray-400 text-xs uppercase tracking-wider mb-1.5 block">Farm Size (Acres)</label>
                  <input value={form.acres} onChange={e => set('acres', e.target.value)} placeholder="e.g. 5" type="number"
                    className="w-full bg-black/30 border border-green-900/40 text-white rounded-xl px-4 py-3 text-sm placeholder-gray-600 transition-all" />
                </div>

                {/* GPS */}
                <div>
                  <label className="text-gray-400 text-xs uppercase tracking-wider mb-1.5 block">GPS Location</label>
                  <button type="button" onClick={detectGPS}
                    className={`w-full glass-green border border-green-700/40 text-green-300 rounded-xl px-4 py-3 text-sm font-medium flex items-center justify-center gap-2 hover:bg-green-900/30 transition-all ${locating ? 'opacity-70' : ''}`}>
                    {locating ? <><span className="animate-spin">⟳</span> Detecting...</> : location ? <>📍 {location.lat}, {location.lng}</> : <>📍 Detect My Location</>}
                  </button>
                </div>
              </>
            )}

            {error && <div className="text-red-400 text-sm text-center bg-red-900/20 rounded-xl py-2">{error}</div>}

            <button type="submit" disabled={loading}
              className={`w-full btn-primary text-white font-bold py-4 rounded-2xl text-base mt-2 flex items-center justify-center gap-2 ${loading ? 'opacity-70' : ''}`}>
              {loading ? <><span className="animate-spin text-xl">⟳</span> Processing...</> : tab === 'login' ? '🔑 Login to Dashboard' : '🌱 Create My Farm Account'}
            </button>
          </form>

          <p className="text-center text-gray-500 text-xs mt-6">
            {tab === 'login' ? "Don't have an account? " : 'Already registered? '}
            <button onClick={() => setTab(tab === 'login' ? 'register' : 'login')} className="text-green-400 hover:text-green-300 font-medium">
              {tab === 'login' ? 'Register Free' : 'Login'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
}
